import{_ as o,l as i,o as e,c as l,v as t,p as d,x as r,d as n,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"建立保持时间","description":"","frontmatter":{"title":"建立保持时间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/setup-hold.md","filePath":"cs/setup-hold.md","lastUpdated":1789023840000}'),c={name:"cs/setup-hold.md"};function h(u,a,F,m,E,f){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="建立保持时间" tabindex="-1">建立保持时间 <a class="header-anchor" href="#建立保持时间" aria-label="Permalink to &quot;建立保持时间&quot;">​</a></h1><div class="epigraph"><p>数据必须在时钟边沿之前稳定一段建立时间，边沿之后再保持一段；否则触发器可能进入亚稳，Q 不是合法比特。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/flipflop-types">D / T / JK 对照</a>钉死了边沿 D 触发器当记忆。本课不重画主从结构，也不从器件噪声统计另起。缺口是：FF 不是「边沿一瞬间任意 D 都行」。它要求 D 在边沿前后各有一段稳定窗口——<strong>建立</strong> \\(t_{su}\\) 与<strong>保持</strong> \\(t_h\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合块有 \\(t_{pd}\\)、\\(t_{cd}\\)。两级 FF 之间夹着组合。缺口是把窗口写成不等式：周期 \\(T\\) 须满足 \\(t_{cq}+t_{pd}+t_{su}\\le T\\)（另加时钟偏斜），否则建立失败，下一拍采样到未稳数据。保持：\\(t_{cd}+t_{hold\\_path}\\ge t_h+t_{skew}\\) 一类，污染太快会冲掉刚锁存的值。</p><p>本课只钉这两条。多周期路径、假路径是工具细节。亚稳若仍发生，解析时间概率衰减，后课跨时钟域才强调同步器。</p><h3 id="加周期不能修保持" tabindex="-1">加周期不能修保持 <a class="header-anchor" href="#加周期不能修保持" aria-label="Permalink to &quot;加周期不能修保持&quot;">​</a></h3><p>建立失败可以降频。保持失败与 \\(T\\) 无关，必须加延迟或改路径。把所有时序问题都「把时钟调慢」，保持违规会留下。</p><p><span class="marginnote">Harris 给出带 skew 的建立/保持不等式。时钟偏斜下一课寄存器仍当理想，多域在<a href="/cs/clock-domain">时钟域</a>才展开。本课先承认 skew 一项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单周期同步：同一时钟的 FF 到 FF。最坏 \\(t_{pd}\\) 管建立，最好 \\(t_{cd}\\) 管保持。缓冲器可以修保持（加大 \\(t_{cd}\\)），但可能恶化建立。</p>',11)),(e(),d(_,null,{default:r(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF1%5B%22FF%20%E5%90%AF%E5%8A%A8%22%5D%20--%3E%20COM%5B%22%E7%BB%84%E5%90%88%20t_pd%20%2F%20t_cd%22%5D%0A%20%20COM%20--%3E%20FF2%5B%22FF%20%E9%87%87%E6%A0%B7%22%5D%0A%20%20FF2%20--%3E%20SU%5B%22%E5%BB%BA%E7%AB%8B%EF%BC%9AT%20%E8%B6%B3%E5%A4%9F%22%5D%0A%20%20FF2%20--%3E%20HD%5B%22%E4%BF%9D%E6%8C%81%EF%BC%9A%E6%B1%A1%E6%9F%93%E5%A4%9F%E6%85%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课单周期 CPU 的 \\(T\\) 由最长指令路径加 \\(t_{su}\\) 决定。流水线把路径切开，每级仍要满足本课不等式——那是体系结构课的叶子，本课只给尺子。毛刺若落在采样窗口外则无事；落在窗口内等于 D 在边沿抖动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把时序签核工具的 SDC 写成教程，不分析锁相环抖动谱。异步输入必须按后课时钟域同步，本课不等式对它不成立。</p><p>后课默认：同步设计先满足建立与保持；周期由建立定下界，保持用路径延迟保证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>建立约束决定最小周期；保持与周期无关。</li><li>\\(t_{pd}\\) 对建立，\\(t_{cd}\\) 对保持。</li><li>降频修不了保持违规。</li><li>出处：Harris and Harris。</li></ul>',7))])}const T=o(c,[["render",h]]);export{B as __pageData,T as default};
